const rawInput = String($input.first().json.chatInput || '').trim();

const supportedTones = [
  'professional',
  'conversational',
  'bold',
  'casual',
  'formal',
  'playful',
  'authoritative',
  'friendly',
  'technical'
];

const tonePattern = new RegExp(
  `\\b(${supportedTones.join('|')})\\b`,
  'i'
);

const toneMatch = rawInput.match(tonePattern);
const tone = toneMatch ? toneMatch[1].toLowerCase() : 'professional';

const urlMatch = rawInput.match(/https?:\/\/\S+/i);
const url = urlMatch ? urlMatch[0] : '';

let productName = rawInput
  .replace(/https?:\/\/\S+/gi, ' ')
  .replace(
    new RegExp(`\\b(${supportedTones.join('|')})\\b(?:\\s+tone)?`, 'gi'),
    ' '
  )
  .replace(/^\s*(please\s+)?(create|generate|build|write)\s+(me\s+)?(a\s+)?/i, '')
  .replace(/^\s*(gtm|go[-\s]?to[-\s]?market)\s+/i, '')
  .replace(/^\s*(campaign|content suite|content)(?:\s+for\b)?\s*/i, '')
  .replace(/^\s*for\b\s*/i, '')
  .replace(/\s+/g, ' ')
  .trim();

const isValid = productName.length > 0;

return [
  {
    json: {
      raw_input: rawInput,
      product_name: productName,
      tone,
      url,
      is_valid: isValid,
      error_message: isValid
        ? ''
        : 'Please provide a product name.'
    }
  }
];

const request = $('Normalize Input').first().json;
const products = $input.all().map(item => item.json);

const normalize = (value) =>
  String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');

const requestedName = normalize(request.product_name);

const matchedProduct = products.find((product) => {
  const catalogName = normalize(product['Product Name']);

  return (
    catalogName === requestedName ||
    catalogName.includes(requestedName) ||
    requestedName.includes(catalogName)
  );
});

if (!matchedProduct) {
  return [
    {
      json: {
        product_found: false,
        requested_product: request.product_name,
        tone: request.tone,
        url: request.url,
        available_products: products.map(
          product => product['Product Name']
        ),
        error_message:
          `Product "${request.product_name}" was not found in the catalog.`
      }
    }
  ];
}

const productData = [
  `Product Name: ${matchedProduct['Product Name']}`,
  `Description: ${matchedProduct['Description']}`,
  `Key Features: ${matchedProduct['Key Features']}`,
  `Pricing: ${matchedProduct['Pricing']}`,
  `Target Audience: ${matchedProduct['Target Audience']}`,
  `Launch Date: ${matchedProduct['Launch Date']}`,
  `Category: ${matchedProduct['Category']}`
].join('\n');

return [
  {
    json: {
      product_found: true,
      requested_product: request.product_name,
      product_name: matchedProduct['Product Name'],
      tone: request.tone,
      url: request.url,
      product_data: productData,
      product_record: matchedProduct,
      error_message: ''
    }
  }
];

const rawStrategy = String(
  $json.text || $json.output || ''
).trim();

const cleanedStrategy = rawStrategy
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

try {
  const strategy = JSON.parse(cleanedStrategy);
  const product = $('Find Product').first().json;

  return {
    json: {
      ...product,
      strategy,
      strategy_parse_success: true,
      strategy_parse_error: ''
    }
  };
} catch (error) {
  const product = $('Find Product').first().json;

  return {
    json: {
      ...product,
      strategy: null,
      strategy_raw: cleanedStrategy,
      strategy_parse_success: false,
      strategy_parse_error: error.message
    }
  };
}

const previousData = $('Parse Strategy').first().json;

// The Structured Output Parser returns the draft as an object.
if (
  $json.output &&
  typeof $json.output === 'object' &&
  !Array.isArray($json.output)
) {
  return {
    json: {
      ...previousData,
      draft: $json.output,
      draft_raw: JSON.stringify($json.output),
      draft_parse_success: true,
      draft_parse_error: ''
    }
  };
}

// Fallback for responses returned as text.
const rawDraft = String(
  $json.text ?? $json.output ?? ''
).trim();

let cleanedDraft = rawDraft
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const firstBrace = cleanedDraft.indexOf('{');
const lastBrace = cleanedDraft.lastIndexOf('}');

if (firstBrace !== -1 && lastBrace > firstBrace) {
  cleanedDraft = cleanedDraft.slice(firstBrace, lastBrace + 1);
}

try {
  const draft = JSON.parse(cleanedDraft);

  return {
    json: {
      ...previousData,
      draft,
      draft_raw: cleanedDraft,
      draft_parse_success: true,
      draft_parse_error: ''
    }
  };
} catch (error) {
  return {
    json: {
      ...previousData,
      draft: null,
      draft_raw: cleanedDraft,
      draft_parse_success: false,
      draft_parse_error:
        error instanceof Error ? error.message : String(error)
    }
  };
}

const rawReview = String(
  $json.text || $json.output || ''
).trim();

const cleanedReview = rawReview
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const previousData = $('Parse Draft').first().json;

try {
  const review = JSON.parse(cleanedReview);

  return {
    json: {
      ...previousData,
      review,
      review_verdict: String(review.verdict || '').toUpperCase(),
      review_parse_success: true,
      review_parse_error: ''
    }
  };
} catch (error) {
  return {
    json: {
      ...previousData,
      review: null,
      review_raw: cleanedReview,
      review_verdict: '',
      review_parse_success: false,
      review_parse_error: error instanceof Error ? error.message : String(error)
    }
  };
}

