const rawRevision = String(
  $json.text || $json.output || ''
).trim();

const cleanedRevision = rawRevision
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const previousData = $('Parse Review').first().json;

try {
  const revisedDraft = JSON.parse(cleanedRevision);

  return {
    json: {
      ...previousData,
      final_content: revisedDraft,
      revision_applied: true,
      revision_parse_success: true,
      revision_parse_error: '',
      final_status: 'pending_human_review'
    }
  };
} catch (error) {
  return {
    json: {
      ...previousData,
      final_content: null,
      revision_raw: cleanedRevision,
      revision_applied: true,
      revision_parse_success: false,
      revision_parse_error:
        error instanceof Error ? error.message : String(error),
      final_status: 'revision_error'
    }
  };
}

const data = $json;
const content = data.final_content;

if (!content) {
  return {
    json: {
      output: 'No final campaign content was available.',
      status: 'final_content_error'
    }
  };
}

const ads = Array.isArray(content.ad_variations)
  ? content.ad_variations
      .map(
        (ad, index) =>
          `### Ad ${index + 1}\n` +
          `**Headline:** ${ad.headline || ''}\n\n` +
          `${ad.body || ''}\n\n` +
          `**Call to action:** ${ad.call_to_action || ''}`
      )
      .join('\n\n')
  : 'No ad variations were returned.';

const revisionMessage = data.revision_applied
  ? 'One automated revision was applied after the independent review.'
  : 'The draft passed the independent review without an automated revision.';

const reviewSummary =
  data.review?.summary || 'No review summary was provided.';

const output = `# ${data.product_name} GTM Campaign

> **Status: Pending human review**
>
> ${revisionMessage}
>
> Nothing has been published automatically.

## LinkedIn Post

${content.linkedin_post?.text || 'Not available'}

## Promotional Email

**Subject:** ${content.promotional_email?.subject || 'Not available'}

**Preview text:** ${content.promotional_email?.preview_text || 'Not available'}

${content.promotional_email?.body || 'Not available'}

## Short Blog

### ${content.short_blog?.title || 'Not available'}

${content.short_blog?.body || 'Not available'}

## Ad Variations

${ads}

## Pre-Revision Reviewer Summary

The following feedback applies to the original draft and triggered the automated revision:
${reviewSummary}

---

A human reviewer must verify all claims, tone, and formatting before publication.`;

return {
  json: {
    ...data,
    output,
    status: 'pending_human_review'
  }
};

const data = $json;

return {
  json: {
    ...data,
    final_content: data.draft,
    revision_applied: false,
    final_status: 'pending_human_review'
  }
};

